<script setup>
import {computed,ref,watch} from 'vue'
import {useMarketFavorites} from '../composables/useMarketFavorites'
import {recordTabs} from '../utils/recordFilters'
import {mockTradeHistory,historyBuckets} from '../utils/mockTradeHistory'
import CurrentTrades from '../components/CurrentTrades.vue'
import TradeHistory from '../components/TradeHistory.vue'
import {useRoute} from 'vue-router'
import {markets,path,fmt} from '../data'
import {session} from '../session'
import Coin from '../components/Coin.vue'
import TradeOrderForm from '../components/TradeOrderForm.vue'
import OptionsChart from '../components/OptionsChart.vue'
import MarketTicker from '../components/MarketTicker.vue'
const route=useRoute(),query=ref(''),category=ref("aiQuant.templates.filterAll"),interval=ref("trade.interval_1h"),records=ref("trade.futuresPositions"),sort=ref(''),sortDescending=ref(true)
const mode=computed(()=>route.params.mode||'futures'),pair=computed(()=>markets.find(m=>(m.id===route.params.symbol||m.name.replace('/','')===route.params.symbol))||markets[0]),rows=computed(()=>markets.filter(m=>(category.value==="aiQuant.templates.filterAll"||category.value==="trade.marketList.favorites"&&favorites.value.includes(m.id)||m.category===category.value)&&m.name.toLowerCase().includes(query.value.toLowerCase())).sort((a,b)=>!sort.value?0:(sortDescending.value?-1:1)*(sort.value==='name'?a.name.localeCompare(b.name):(a[sort.value]||0)-(b[sort.value]||0))))
const title=computed(()=>({futures:"assets.todayPnl.futures",spot:"common.spot",options:"common.options"}[mode.value]))
const emptyRecord=computed(()=>({'trade.futuresPositions':'positions','trade.futuresHistory':'positionHistory','trade.futuresOrders':'openOrders','trade.futuresOrdersHistory':'orderHistory','trade.optionsOrders':'optionsOrders','trade.spotOrders':'spotOpenOrders','trade.spotOrdersHistory':'spotOrdersHistory'}[records.value]||'positions'))
const recordNotice=ref('')
watch(records,()=>recordNotice.value='')
const displayedOrders=computed(()=>{
  const tab=recordTabs[records.value]
  return [...session.orders,...mockTradeHistory].filter(order=>order.kind===tab.kind&&order.bucket===tab.bucket).sort((a,b)=>(b.createdAt||0)-(a.createdAt||0))
})
function changeSort(key){if(sort.value===key)sortDescending.value=!sortDescending.value;else{sort.value=key;sortDescending.value=true}}
const {favorites,favorite}=useMarketFavorites('trade-v2-favorites')

</script>
<template><div class="trading-terminal" :class="{'options-terminal':mode==='options'}"><div class="instrument-bar"><div class="coin-label"><Coin :symbol="pair.symbol"/><strong>{{ $t(pair.name) }}</strong><button class="instrument-favorite" :aria-label="$t(favorites.includes(pair.id)?'common.unfavoriteMarket':'common.favoriteMarket',{symbol:pair.name})" :aria-pressed="favorites.includes(pair.id)" @click="favorite(pair.id)">{{ favorites.includes(pair.id)?'★':'☆' }}</button></div><strong :class="pair.change<0?'negative':'positive'">{{ $t(fmt(pair.price)) }}</strong><span :class="pair.change<0?'negative':'positive'">{{ $t(pair.change) }}%</span><span><small>{{ $t("home.markets.colChange") }}</small>{{ $t(fmt(pair.price-pair.price/(1+pair.change/100))) }}</span><span><small>{{ $t("trade.24hHigh") }}</small>{{ $t(fmt(pair.price*1.064)) }}</span><span><small>{{ $t("trade.24hLow") }}</small>{{ $t(fmt(pair.price*.979)) }}</span><span><small>{{ $t("home.markets.colVolume") }}</small>{{ $compact(pair.volume) }}</span></div>
<div class="terminal-grid"><aside class="terminal-panel pair-panel"><input v-model="query" :aria-label="$t(&quot;trade.searchSymbol&quot;)" :placeholder="$t(&quot;common.search&quot;)"/><nav class="trade-modes" :style="{'--mode-index':['futures','options','spot'].indexOf(mode)}"><RouterLink v-for="(label,key) in {futures:&quot;assets.todayPnl.futures&quot;,options:&quot;common.options&quot;,spot:&quot;common.spot&quot;}" :key="key" :class="{active:mode===key}" :to="path('/trade/'+key+'/'+pair.id)">{{ $t(label) }}</RouterLink></nav><div class="pair-categories"><button v-for="c in [&quot;trade.marketList.favorites&quot;,&quot;aiQuant.templates.filterAll&quot;,&quot;home.products.perpTag1&quot;,&quot;aiQuant.market.forex&quot;,&quot;aiQuant.market.stock&quot;]" :key="c" :class="{active:category===c}" @click="category=c">{{ $t(c) }}</button></div><div class="pair-sort"><button @click="changeSort('name')">{{ $t('aiQuant.templates.fields.supportedSymbols') }} ↕</button><button @click="changeSort('volume')">{{ $t('trade.turnover') }} ↕</button><button @click="changeSort('price')">{{ $t('home.markets.colPrice') }} ↕</button><button @click="changeSort('change')">{{ $t('trade.chg') }} ↕</button></div><div class="pair-list"><div v-for="m in rows" :key="m.id" class="pair-row" :class="{selected:m.id===pair.id}"><button :aria-label="$t(favorites.includes(m.id)?'common.unfavoriteMarket':'common.favoriteMarket',{symbol:m.name})" :aria-pressed="favorites.includes(m.id)" @click="favorite(m.id)">{{ $t(favorites.includes(m.id)?'★':'☆') }}</button><RouterLink :to="path('/trade/'+mode+'/'+m.id)"><span class="coin-label"><Coin :symbol="m.symbol"/><span>{{ $t(m.name) }}<small class="mini-label">{{ $compact(m.volume) }}</small></span></span><span>{{ $t(fmt(m.price)) }}<small :class="m.change<0?'negative':'positive'">{{ $t(m.change) }}%</small></span></RouterLink></div><div v-if="!rows.length" class="empty">{{ $t("markets.ui.noMatchingMarkets") }}</div></div></aside>
<section class="terminal-panel chart-panel"><div class="timeframes"><button v-for="t in [&quot;trade.interval_1m&quot;,&quot;trade.interval_5m&quot;,&quot;trade.interval_15m&quot;,&quot;trade.interval_30m&quot;,&quot;trade.interval_1h&quot;,&quot;trade.interval_1d&quot;,&quot;trade.interval_1w&quot;,&quot;trade.interval_1M&quot;,&quot;trade.interval_1y&quot;]" :class="{active:interval===t}" @click="interval=t">{{ $t(t) }}</button></div><div class="ohlc"><span>{{ $t('trade.open') }}: <b>{{ fmt(pair.price*1.0041) }}</b></span><span>{{ $t('trade.high') }}: <b>{{ fmt(pair.price*1.0042) }}</b></span><span>{{ $t('trade.low') }}: <b>{{ fmt(pair.price*.996) }}</b></span><span>{{ $t('trade.close') }}: <b>{{ fmt(pair.price) }}</b></span></div><OptionsChart :price="pair.price" :interval="interval"/></section>
<section class="terminal-panel orderbook"><template v-if="mode==='options'"><div class="options-book-title"><h2>{{ $t('trade.orderBook') }}</h2><strong :class="pair.change<0?'negative':'positive'">{{ fmt(pair.price) }}</strong></div><div class="split-book"><div v-for="side in ['ask','bid']" :key="side"><div class="book-head"><span>{{ $t('trade.orderPrice') }}</span><span>{{ $t('trade.amount') }}</span><span>{{ $t('trade.total') }}</span></div><div v-for="n in 8" :key="n" class="book-row" :class="{bid:side==='bid'}" :style="{'--depth':(15+n*9)+'%'}" :aria-label="$t('trade.orderPrice')+' '+fmt(pair.price+(side==='ask'?1:-1)*n*pair.price*.000002)"><span :class="side==='ask'?'negative':'positive'">{{ fmt(pair.price+(side==='ask'?1:-1)*n*pair.price*.000002) }}</span><span>{{ (n*.0017).toFixed(5) }}</span><span>{{ (n*(n+1)*.0017/2).toFixed(5) }}</span></div></div></div><div class="options-book-mid" :class="pair.change<0?'negative':'positive'">{{ fmt(pair.price) }} {{ pair.change<0?'↓':'↑' }}</div><div class="depth-ratio"><span>B 64.20%</span><span>35.80% S</span></div></template><template v-else><h2>{{ $t("trade.orderBook") }}</h2><div class="book-head"><span>{{ $t("trade.ui.priceUsd") }}</span><span>{{ $t("aiQuant.quantFund.interestRecords.table.amount") }}</span><span>{{ $t("trade.total") }}</span></div><div v-for="n in 9" :key="'ask'+n" class="book-row" :style="{'--depth':(n*7+13)+'%'}"><span class="negative">{{ $t(fmt(pair.price+(10-n)*pair.price*.00002)) }}</span><span>{{ $t((n*.0013).toFixed(4)) }}</span><span>{{ $t((n*.0037).toFixed(4)) }}</span></div><div class="book-price negative">{{ $t(fmt(pair.price)) }} ↓ <small>≈ {{ $t(fmt(pair.price)) }}{{ ' USDT' }}</small></div><div v-for="n in 9" :key="'bid'+n" class="book-row bid" :style="{'--depth':(n*9)+'%'}"><span class="positive">{{ $t(fmt(pair.price-n*pair.price*.00002)) }}</span><span>{{ $t((n*.0017).toFixed(4)) }}</span><span>{{ $t((n*.0041).toFixed(4)) }}</span></div></template></section>
<section class="terminal-panel order-panel"><nav class="trade-modes" :style="{'--mode-index':['futures','options','spot'].indexOf(mode)}"><RouterLink v-for="(label,key) in {futures:&quot;trade.futuresOrder&quot;,options:&quot;trade.optionsOrder&quot;,spot:&quot;common.spot&quot;}" :key="key" :class="{active:mode===key}" :to="path('/trade/'+key+'/'+pair.id)">{{ $t(label) }}</RouterLink></nav><TradeOrderForm :mode="mode" :pair="pair"/></section></div>
<section class="terminal-panel records-panel"><div class="record-tabs"><button v-for="r in [&quot;trade.futuresPositions&quot;,&quot;trade.futuresHistory&quot;,&quot;trade.futuresOrders&quot;,&quot;trade.futuresOrdersHistory&quot;,&quot;trade.optionsOrders&quot;,&quot;trade.spotOrders&quot;,&quot;trade.spotOrdersHistory&quot;]" :class="{active:records===r}" @click="records=r">{{ $t(r) }}</button></div><p v-if="recordNotice" role="status" class="record-notice">{{ recordNotice }}</p><div v-if="!displayedOrders.length" class="empty"><svg class="records-empty-icon" viewBox="0 0 64 64" fill="none" aria-hidden="true"><path d="M8 12h48v12H8zM12 24v30h30M22 33h12"/><circle cx="43" cy="44" r="8"/><path d="m49 50 8 8"/></svg>{{ $t('trade.empty.'+emptyRecord+'.title') }}<p>{{ $t('trade.empty.'+emptyRecord+'.description') }}</p></div><TradeHistory v-else-if="historyBuckets.includes(recordTabs[records].bucket)" :rows="displayedOrders" :bucket="recordTabs[records].bucket"/><CurrentTrades v-else @complete="recordNotice=$event" :rows="displayedOrders" :bucket="recordTabs[records].bucket"/></section><div class="options-status"><span class="positive">⌁ {{ $t('trade.network.stable') }}</span><span class="negative">{{ $t('trade.hot') }}</span><MarketTicker :rows="markets"/></div></div></template>
